# Encapsulates the vcpkg system 
class VcpkgRepo:
    CMAKE_TEMPLATE = """
# this file auto-generated by hifi_vcpkg.py
get_filename_component(CMAKE_TOOLCHAIN_FILE "{}" ABSOLUTE CACHE)
get_filename_component(CMAKE_TOOLCHAIN_FILE_UNCACHED "{}" ABSOLUTE)
set(VCPKG_INSTALL_ROOT "{}")
set(VCPKG_TOOLS_DIR "{}")
set(VCPKG_TARGET_TRIPLET "{}")
"""

    CMAKE_TEMPLATE_NON_ANDROID = """
# If the cached cmake toolchain path is different from the computed one, exit
if(NOT (CMAKE_TOOLCHAIN_FILE_UNCACHED STREQUAL CMAKE_TOOLCHAIN_FILE))
    message(FATAL_ERROR "CMAKE_TOOLCHAIN_FILE has changed, please wipe the build directory and rerun cmake")
endif()
"""

    def __init__(self, args):
        self.args = args
        # our custom ports, relative to the script location
        self.sourcePortsPath = args.ports_path
        self.vcpkgBuildType = args.vcpkg_build_type
        if (self.vcpkgBuildType):
            self.id = hifi_utils.hashFolder(self.sourcePortsPath)[:8] + "-" + self.vcpkgBuildType
        else:
            self.id = hifi_utils.hashFolder(self.sourcePortsPath)[:8]
        self.configFilePath = os.path.join(args.build_root, 'vcpkg.cmake')
        # The noClean flag indicates we're doing weird dependency maintenance stuff
        # i.e. we've got an explicit checkout of vcpkg and we don't want the script to 
        # do stuff it might otherwise do.  It typically indicates that we're using our 
        # own git checkout of vcpkg and manually managing it
        self.noClean = False

        # OS dependent information
        system = platform.system()

        if 'TIVOLI_VCPKG_PATH' in os.environ:
            self.path = os.environ['TIVOLI_VCPKG_PATH']
            self.noClean = True
        elif self.args.vcpkg_root is not None:
            self.path = args.vcpkg_root
            self.noClean = True
        else:
            defaultBasePath = os.path.expanduser('~/tivoli/vcpkg')
            self.basePath = os.getenv('TIVOLI_VCPKG_BASE', defaultBasePath)
            if self.args.android:
                self.basePath = os.path.join(self.basePath, 'android')
            if (not os.path.isdir(self.basePath)):
                os.makedirs(self.basePath)
            self.path = os.path.join(self.basePath, self.id)

        print("Using vcpkg path {}".format(self.path))
        lockDir, lockName = os.path.split(self.path)
        lockName += '.lock'
        if not os.path.isdir(lockDir):
            os.makedirs(lockDir)

        self.lockFile = os.path.join(lockDir, lockName)
        self.tagFile = os.path.join(self.path, '.id')
        self.prebuildTagFile = os.path.join(self.path, '.prebuild')
        # A format version attached to the tag file... increment when you want to force the build systems to rebuild 
        # without the contents of the ports changing
        self.version = 1

        # when next vcpkg release, lets unify version again
        if system == 'Darwin':
            self.vcpkgVersion = "5ddd7f02689b7c5aab78711d77f61db5d2e5e79c"
        else:
            self.vcpkgVersion = "2021.05.12"

        self.tagContents = "{}_{}".format(self.id, self.version)
        self.bootstrapEnv = os.environ.copy()
        self.buildEnv = os.environ.copy()
        self.prebuiltArchive = None
        usePrebuilt = ('CI_BUILD' in os.environ) and os.environ["CI_BUILD"] == "Github" and (not self.noClean)

        if 'Windows' == system:
            self.exe = os.path.join(self.path, 'vcpkg.exe')
            self.bootstrapCmds = [ os.path.join(self.path, 'bootstrap-vcpkg.bat'), '-disableMetrics' ]
            # self.vcpkgUrl = 'https://cdn.tivolicloud.com/dependencies/vcpkg/vcpkg-win32-client.zip'
            # self.vcpkgHash = 'a650db47a63ccdc9904b68ddd16af74772e7e78170b513ea8de5a3b47d032751a3b73dcc7526d88bcb500753ea3dd9880639ca842bb176e2bddb1710f9a58cd3'
            self.hostTriplet = 'x64-windows'
            self.loadMsvcEnv()

            if usePrebuilt:
               self.prebuiltArchive = "https://cdn.tivolicloud.com/dependencies/vcpkg/builds/vcpkg-win32.zip"
        
        elif 'Darwin' == system:
            self.exe = os.path.join(self.path, 'vcpkg')
            self.bootstrapCmds = [ os.path.join(self.path, 'bootstrap-vcpkg.sh'), '-disableMetrics', "-allowAppleClang" ]
            # self.vcpkgUrl = 'https://cdn.tivolicloud.com/dependencies/vcpkg/vcpkg-osx-client.tar'
            # self.vcpkgHash = '519d666d02ef22b87c793f016ca412e70f92e1d55953c8f9bd4ee40f6d9f78c1df01a6ee293907718f3bbf24075cc35492fb216326dfc50712a95858e9cbcb4d'
            # Build natively: arm64-osx on Apple Silicon, x64-osx on Intel.
            if platform.machine().lower() in ("arm64", "aarch64"):
                self.hostTriplet = 'arm64-osx'
            else:
                self.hostTriplet = 'x64-osx'

            if usePrebuilt:
                self.prebuiltArchive = "https://cdn.tivolicloud.com/dependencies/vcpkg/builds/vcpkg-osx.tgz"

            macVersion = hifi_utils.getMacVersion()
            self.bootstrapEnv["MACOSX_DEPLOYMENT_TARGET"] = str(macVersion[0]) + "." + str(macVersion[1])
            # The dependencies must not require a newer macOS than the Qt build and interface itself
            # (the top-level CMakeLists.txt exports MACOSX_DEPLOYMENT_TARGET before running prebuild.py).
            if 'MACOSX_DEPLOYMENT_TARGET' not in self.buildEnv:
                self.buildEnv["MACOSX_DEPLOYMENT_TARGET"] = "12.0"

            # vcpkg uses tools for 10.15 that dont work on older version of macOS
            if macVersion[0] <= 10 and macVersion[1] <= 14:
                self.bootstrapCmds.append("-useSystemBinaries")
                self.buildEnv["VCPKG_FORCE_SYSTEM_BINARIES"] = "1"

        else:
            self.exe = os.path.join(self.path, 'vcpkg')
            self.bootstrapCmds = [ os.path.join(self.path, 'bootstrap-vcpkg.sh'), '-disableMetrics' ]
            # self.vcpkgUrl = 'https://cdn.tivolicloud.com/dependencies/vcpkg/vcpkg-linux-client.tar'
            # self.vcpkgHash = '6a1ce47ef6621e699a4627e8821ad32528c82fce62a6939d35b205da2d299aaa405b5f392df4a9e5343dd6a296516e341105fbb2dd8b48864781d129d7fba10d'
            self.hostTriplet = 'x64-linux'
            # The 2021 vcpkg tool uses std::uint64_t without including <cstdint>, which GCC 13
            # (Ubuntu 24.04) no longer pulls in through other headers.
            self.bootstrapEnv["CXXFLAGS"] = (self.bootstrapEnv.get("CXXFLAGS", "") + " -include cstdint").strip()

            if platform.machine() == "aarch64":
                self.bootstrapCmds.append("-useSystemBinaries")
                self.buildEnv["VCPKG_FORCE_SYSTEM_BINARIES"] = "1"
                self.hostTriplet = "arm64-linux"

        if self.args.android:
            self.triplet = 'arm64-android'
            self.androidPackagePath = os.getenv('HIFI_ANDROID_PRECOMPILED', os.path.join(self.path, 'android'))
        else:
            self.triplet = self.hostTriplet

    def loadMsvcEnv(self):
        # The Windows triplet chainloads a toolchain so ports build with Ninja (see copyTripletForBuildType),
        # and then vcpkg expects the compiler in the environment instead of setting it up itself.
        # Load the v142 (MSVC 14.29) compiler, the one Qt was built with, unless a developer prompt already has.
        if 'VCTOOLSVERSION' in self.buildEnv:
            return
        vswhere = os.path.join(os.environ.get('ProgramFiles(x86)', r'C:\Program Files (x86)'),
            'Microsoft Visual Studio', 'Installer', 'vswhere.exe')
        if not os.path.isfile(vswhere):
            raise RuntimeError('Visual Studio not found: install it with the MSVC v142 (14.29) build tools')
        vsPath = subprocess.check_output([vswhere, '-latest', '-products', '*',
            '-requires', 'Microsoft.VisualStudio.Component.VC.14.29.16.11.x86.x64',
            '-property', 'installationPath'], universal_newlines=True).strip()
        if not vsPath:
            raise RuntimeError('Visual Studio has no MSVC v142 (14.29) build tools: add the component '
                '"MSVC v142 - VS 2019 C++ x64/x86 build tools" in the Visual Studio Installer')
        vcvarsall = os.path.join(vsPath, 'VC', 'Auxiliary', 'Build', 'vcvarsall.bat')
        print("Loading the MSVC 14.29 environment from {}".format(vcvarsall))
        output = subprocess.check_output('"{}" x64 -vcvars_ver=14.29 >nul && set'.format(vcvarsall),
            shell=True, universal_newlines=True)
        # vcpkg builds each port in a clean environment: keep everything vcvarsall set or changed
        keep = [v for v in self.buildEnv.get('VCPKG_KEEP_ENV_VARS', '').split(';') if v]
        for line in output.splitlines():
            name, sep, value = line.partition('=')
            name = name.upper()
            # VS 2022 bundles its own vcpkg and points VCPKG_ROOT at it: keep ours
            if name.startswith('VCPKG_'):
                continue
            if sep and self.buildEnv.get(name) != value:
                self.buildEnv[name] = value
                # Not PATH: vcpkg writes its own "Path" too, and the two make tools pick either
                if name != 'PATH':
                    keep.append(name)
        # The triplet puts the MSVC tools in front of vcpkg's PATH from this
        self.buildEnv['HIFI_MSVC_PATH'] = self.buildEnv['PATH']
        keep.append('HIFI_MSVC_PATH')
        self.buildEnv['VCPKG_KEEP_ENV_VARS'] = ';'.join(keep)

    def patchVcpkgScripts(self):
        # This vcpkg fetches pkg-config from MSYS2's 32-bit MinGW repository, which MSYS2 has retired:
        # fetch the last pkg-config from its x86_64 repository instead
        self.patchVcpkgScript('vcpkg_find_acquire_program.cmake', [
            ('"https://repo.msys2.org/mingw/i686/mingw-w64-i686-pkg-config-${VERSION}-any.pkg.tar.zst"\n'
             '            54f8dad3b1a36a4515db47825a3214fbd2bd82f604aec72e7fb8d79068095fda3c836fb2296acd308522d6e12ce15f69e0c26dcf4eb0681fd105d057d912cdb7',
             '"https://repo.msys2.org/mingw/mingw64/mingw-w64-x86_64-pkg-config-0.29.2-6-any.pkg.tar.zst"\n'
             '            8dc4045e16314e24d8361336f989c97d2067ab3476d37e01c98b240cc299f24c8318ac48753653721e0118e0d69eba91f593e7ab0ec1ef3052cbd419595fbfe7'),
            ('"https://repo.msys2.org/mingw/i686/mingw-w64-i686-libwinpthread-${LIBWINPTHREAD_VERSION}-any.pkg.tar.zst"\n'
             '            2c3d9e6b2eee6a4c16fd69ddfadb6e2dc7f31156627d85845c523ac85e5c585d4cfa978659b1fe2ec823d44ef57bc2b92a6127618ff1a8d7505458b794f3f01c',
             '"https://repo.msys2.org/mingw/mingw64/mingw-w64-x86_64-libwinpthread-git-12.0.0.r747.g1a99f8514-1-any.pkg.tar.zst"\n'
             '            dd6c5ac767f6ef39afaef822796d8da65bb09ceee35d19332922012266f384cd1907f3f73efa70e5160e2287f5804f2a49788cb16af1a98ba9dffba832e4ba92'),
            ('"${PKGCONFIG_ROOT}/mingw32/bin/pkg-config.exe"', '"${PKGCONFIG_ROOT}/mingw64/bin/pkg-config.exe"'),
            # A current NASM instead of 2.15.05 (from 2020)
            ('set(NASM_VERSION 2.15.05)', 'set(NASM_VERSION 2.16.03)'),
            ('9412b8caa07e15eac8f500f6f8fab9f038d95dc25e0124b08a80645607cf5761225f98546b52eac7b894420d64f26c3cbf22c19cd286bbe583f7c964256c97ed',
             '8e93ef2378bd5fafe505f8a2940b1e83f2a7563f994ecc82b5d081d178c7ade80a6bad17d52f693432b44e28c2420f68159b36ffea742f4b7c91ef3a855bcd0c'),
        ])
        # The chainloaded toolchain (see copyTripletForBuildType) makes the toolset "external", which
        # MSBuild doesn't know: build MSBuild ports with v142, as loadMsvcEnv set up
        for script in ('vcpkg_build_msbuild.cmake', 'vcpkg_install_msbuild.cmake'):
            self.patchVcpkgScript(script, [(
                '        set(_csc_PLATFORM_TOOLSET ${VCPKG_PLATFORM_TOOLSET})\n',
                '        set(_csc_PLATFORM_TOOLSET ${VCPKG_PLATFORM_TOOLSET})\n'
                '        if(_csc_PLATFORM_TOOLSET STREQUAL "external")\n'
                '            set(_csc_PLATFORM_TOOLSET v142)\n'
                '        endif()\n')])

    def patchVcpkgScript(self, name, replacements):
        script = os.path.join(self.path, 'scripts', 'cmake', name)
        with open(script, 'r') as f:
            contents = f.read()
        patched = contents
        for old, new in replacements:
            if new not in patched:
                patched = patched.replace(old, new)
        if patched != contents:
            print("Patching vcpkg's {}".format(name))
            with open(script, 'w') as f:
                f.write(patched)

    def writeEnv(self, var, value=""):
        envPath = os.path.join(self.args.build_root, "_env")
        if not os.path.isdir(envPath):
            os.mkdir(envPath)
        with open(os.path.join(envPath, var + ".txt"), "w") as fp:
            fp.write(value)
            fp.close()

    def readEnv(self, var):
        with open(os.path.join(self.args.build_root, '_env', var + ".txt")) as fp:
            return fp.read()

    def copyEnvToVcpkg(self):
        print("Passing on variables to vcpkg")
        srcEnv = os.path.join(self.args.build_root, "_env")
        destEnv = os.path.join(self.path, "_env")

        if path.exists(destEnv):
            shutil.rmtree(destEnv)

        shutil.copytree(srcEnv, destEnv)

    def upToDate(self):
        # Prevent doing a clean if we've explcitly set a directory for vcpkg
        if self.noClean:
            return True

        if self.args.force_build:
            print("Force build, out of date")
            return False
        if not os.path.isfile(self.exe):
            print("Exe file {} not found, out of date".format(self.exe))
            return False
        if not os.path.isfile(self.tagFile):
            print("Tag file {} not found, out of date".format(self.tagFile))
            return False
        with open(self.tagFile, 'r') as f:
            storedTag = f.read()
        if storedTag != self.tagContents:
            print("Tag file {} contents don't match computed tag {}, out of date".format(self.tagFile, self.tagContents))
            return False
        return True

    def clean(self):
        print("Cleaning vcpkg installation at {}".format(self.path))
        if os.path.isdir(self.path):
            print("Removing {}".format(self.path))
            shutil.rmtree(self.path, ignore_errors=True)

    # Make sure the VCPKG prerequisites are all there.
    def bootstrap(self):
        if self.upToDate():
            return

        if self.prebuiltArchive is not None:
            return

        self.clean()
        downloadVcpkg = False
        if self.args.force_bootstrap:
            print("Forcing bootstrap")
            downloadVcpkg = True

        if not downloadVcpkg and not os.path.isfile(self.exe):
            print("Missing executable, boot-strapping")
            downloadVcpkg = True
        
        # Make sure we have a vcpkg executable
        testFile = os.path.join(self.path, '.vcpkg-root')
        if not downloadVcpkg and not os.path.isfile(testFile):
            print("Missing {}, bootstrapping".format(testFile))
            downloadVcpkg = True

        if downloadVcpkg:
            # print("Cloning vcpkg from github to {}".format(self.path))
            # hifi_utils.executeSubprocess(['git', 'clone', 'https://github.com/microsoft/vcpkg.git', self.path])
            
            print("Download vcpkg from GitHub to {}".format(self.path))

            hifi_utils.downloadAndExtract(
                "https://codeload.github.com/microsoft/vcpkg/zip/" + self.vcpkgVersion, self.path, isZip=True
            )
            vcpkg_extract_dir = os.path.join(self.path, "vcpkg-" + self.vcpkgVersion)

            for filename in os.listdir(vcpkg_extract_dir):
                shutil.move(os.path.join(vcpkg_extract_dir, filename), os.path.join(self.path, filename))
            
            os.rmdir(vcpkg_extract_dir)

            if platform.system() != "Windows":
                hifi_utils.executeSubprocess(["chmod", "+x", os.path.join(self.path, "bootstrap-vcpkg.sh")])

            print("Bootstrapping vcpkg")
            hifi_utils.executeSubprocess(self.bootstrapCmds, folder=self.path, env=self.bootstrapEnv)      

        print("Replacing port files")
        portsPath = os.path.join(self.path, 'ports')
        if (os.path.islink(portsPath)):
            os.unlink(portsPath)
        if (os.path.isdir(portsPath)):
            shutil.rmtree(portsPath, ignore_errors=True)
        shutil.copytree(self.sourcePortsPath, portsPath)

    def run(self, commands):
        # TODO: causes Error: Invalid vcpkg root directory /interface/build/TIVOLI_VCPKG/5317b356-release/interface/build/TIVOLI_VCPKG/5317b356-release: No such file or directory
        # actualCommands = [self.exe, '--vcpkg-root', self.path]

        # The vcpkg tool binary may be x86_64-only; macOS runs it under Rosetta automatically.
        # We no longer force `arch -x86_64`, since the build now targets the native architecture.
        actualCommands = [self.exe]
        actualCommands.extend(commands)
        
        print("Running command")
        print(actualCommands)
        hifi_utils.executeSubprocess(actualCommands, folder=self.path, env=self.buildEnv)

    def copyTripletForBuildType(self, triplet):
        print('Copying triplet ' + triplet + ' to have build type ' + self.vcpkgBuildType)

        tripletPath = os.path.join(self.path, 'triplets', triplet + '.cmake')
        if not os.path.isfile(tripletPath):
            tripletPath = os.path.join(self.path, 'triplets/community', triplet + '.cmake')
            if not os.path.isfile(tripletPath):
                raise RuntimeError('Triplet ' + triplet + ' not found')

        tripletForBuildTypePath = os.path.join(self.path, 'triplets', self.getTripletWithBuildType(triplet) + '.cmake')
        shutil.copy(tripletPath, tripletForBuildTypePath)

        with open(tripletForBuildTypePath, "a") as tripletForBuildTypeFile:
            tripletForBuildTypeFile.write("set(VCPKG_BUILD_TYPE " + self.vcpkgBuildType + ")\n")
            if platform.system() == "Linux":
                # The ports' 2021 sources use std::uint32_t and friends without including <cstdint>,
                # which GCC 13 (Ubuntu 24.04) no longer pulls in through other headers.
                tripletForBuildTypeFile.write("set(VCPKG_C_FLAGS \"\")\n")
                tripletForBuildTypeFile.write("set(VCPKG_CXX_FLAGS \"-include cstdint\")\n")
            if platform.system() == 'Windows':
                # Build every port with Ninja and the v142 compiler from VS 2022's installer: without a
                # chainload toolchain, this vcpkg asks for the "Visual Studio 16 2019" generator by name,
                # which only a full VS 2019 install provides.
                tripletForBuildTypeFile.write('set(VCPKG_CHAINLOAD_TOOLCHAIN_FILE "${CMAKE_CURRENT_LIST_DIR}/../scripts/toolchains/windows.cmake")\n')
                # vcpkg resets PATH for each port: put the MSVC tools loadMsvcEnv set up in front of it
                # (CMake finds cl without them, but jom, nmake and gn builds run it from PATH)
                tripletForBuildTypeFile.write('if(DEFINED ENV{HIFI_MSVC_PATH})\n'
                    '    set(ENV{PATH} "$ENV{HIFI_MSVC_PATH};$ENV{PATH}")\n'
                    'endif()\n')

    def getTripletWithBuildType(self, triplet):
        if not self.vcpkgBuildType:
            return triplet
        return triplet + '-' + self.vcpkgBuildType

    def setupDependencies(self, qt=None):
        if self.prebuiltArchive:
            if not os.path.isfile(self.prebuildTagFile):
                print('Extracting ' + self.prebuiltArchive + ' to ' + self.path)
                hifi_utils.downloadAndExtract(self.prebuiltArchive, self.path)
                self.writePrebuildTag()
            return
            
        if qt is not None:
            self.buildEnv['QT_CMAKE_PREFIX_PATH'] = qt
            # required for building quazip because cmake in vcpkg port cant read env vars
            self.writeEnv("QT_CMAKE_PREFIX_PATH", qt)

        self.copyEnvToVcpkg()

        # Special case for android, grab a bunch of binaries
        # FIXME remove special casing for android builds eventually
        if self.args.android:
            print("Installing Android binaries")
            self.setupAndroidDependencies()

        if platform.system() == 'Windows':
            self.patchVcpkgScripts()

        print("Installing host tools")
        if (self.vcpkgBuildType):
            self.copyTripletForBuildType(self.hostTriplet)
        hostTriplet = self.getTripletWithBuildType(self.hostTriplet)
        # Pass the host triplet explicitly: when the vcpkg tool runs under Rosetta it would
        # otherwise detect the host as x64-osx and build host tools for the wrong architecture.
        self.run(['install', '--triplet', hostTriplet, '--host-triplet', hostTriplet, 'hifi-host-tools'])

        # If not android, install the hifi-client-deps libraries (only the server's for a server-only
        # build: the client's include prebuilt SDKs, such as Leap Motion and Steamworks, that a server never uses)
        if not self.args.android:
            print("Installing build dependencies")
            if (self.vcpkgBuildType):
                self.copyTripletForBuildType(self.triplet)
            depsPackage = 'hifi-server-deps' if self.args.server_only else 'hifi-client-deps'
            self.run(['install', '--triplet', self.getTripletWithBuildType(self.triplet), '--host-triplet', hostTriplet, depsPackage])

    def cleanBuilds(self):
        if self.noClean:
            return
        # Remove temporary build artifacts
        builddir = os.path.join(self.path, 'buildtrees')
        if os.path.isdir(builddir):
            print("Wiping build trees")
            shutil.rmtree(builddir, ignore_errors=True)

    # Removes large files used to build the vcpkg, for CI purposes.
    def cleanupDevelopmentFiles(self):
        # delete all in downloads except tools
        downloads_dir = os.path.join(self.path, "downloads")
        downloads = map(lambda filename: os.path.join(downloads_dir, filename),
            filter(lambda filename: filename != "tools",
                os.listdir(downloads_dir) if os.path.isdir(downloads_dir) else []
            )
        )

        # delete all in packages except openssl
        packages_dir = os.path.join(self.path, "packages")
        packages = map(lambda filename: os.path.join(packages_dir, filename),
            filter(lambda filename: not filename.startswith("openssl"),
                os.listdir(packages_dir) if os.path.isdir(packages_dir) else []
            )
        )

        for filePath in list(downloads) + list(packages):
            if os.path.isdir(filePath):
                shutil.rmtree(filePath, ignore_errors=True)
            else:
                os.remove(filePath)

    def setupAndroidDependencies(self):
        # vcpkg prebuilt
        if not os.path.isdir(os.path.join(self.path, 'installed', 'arm64-android')):
            dest = os.path.join(self.path, 'installed')
            url = "https://cdn.tivolicloud.com/dependencies/vcpkg/vcpkg-arm64-android.tar.gz"
            # FIXME I don't know why the hash check frequently fails here.  If you examine the file later it has the right hash
            #hash = "832f82a4d090046bdec25d313e20f56ead45b54dd06eee3798c5c8cbdd64cce4067692b1c3f26a89afe6ff9917c10e4b601c118bea06d23f8adbfe5c0ec12bc3"
            #hifi_utils.downloadAndExtract(url, dest, hash)
            hifi_utils.downloadAndExtract(url, dest)

        print("Installing additional android archives")
        androidPackages = hifi_android.getPlatformPackages()
        for packageName in androidPackages:
            package = androidPackages[packageName]
            dest = os.path.join(self.androidPackagePath, packageName)
            if os.path.isdir(dest):
                continue
            url = hifi_android.getPackageUrl(package)
            zipFile = package['file'].endswith('.zip')
            print("Android archive {}".format(package['file']))
            hifi_utils.downloadAndExtract(url, dest, isZip=zipFile, hash=package['checksum'], hasher=hashlib.md5())

    def writeTag(self):
        if self.noClean:
            return
        print("Writing tag {} to {}".format(self.tagContents, self.tagFile))
        if not os.path.isdir(self.path):
            os.makedirs(self.path)
        with open(self.tagFile, 'w') as f:
            f.write(self.tagContents)

    def writePrebuildTag(self):
        print("Writing tag {} to {}".format(self.tagContents, self.tagFile))
        with open(self.prebuildTagFile, 'w') as f:
            f.write(self.tagContents)

    def fixupCmakeScript(self):
        cmakeScript = os.path.join(self.path, 'scripts/buildsystems/vcpkg.cmake')
        newCmakeScript = cmakeScript + '.new'
        isFileChanged = False
        removalPrefix = "set(VCPKG_TARGET_TRIPLET "
        # Open original file in read only mode and dummy file in write mode
        with open(cmakeScript, 'r') as read_obj, open(newCmakeScript, 'w') as write_obj:
            # Line by line copy data from original file to dummy file
            for line in read_obj:
                if not line.startswith(removalPrefix):
                    write_obj.write(line)
                else:
                    isFileChanged = True

        if isFileChanged:
            shutil.move(newCmakeScript, cmakeScript)
        else:
            os.remove(newCmakeScript)

    def writeConfig(self):
        print("Writing cmake config to {}".format(self.configFilePath))
        # Write out the configuration for use by CMake
        cmakeScript = os.path.join(self.path, 'scripts/buildsystems/vcpkg.cmake')
        installPath = os.path.join(self.path, 'installed', self.getTripletWithBuildType(self.triplet))
        if self.args.android:
            installPath = os.path.join(self.path, 'installed', self.triplet)
        toolsPath = os.path.join(self.path, 'installed', self.getTripletWithBuildType(self.hostTriplet), 'tools')

        cmakeTemplate = VcpkgRepo.CMAKE_TEMPLATE
        if self.args.android:
            precompiled = os.path.realpath(self.androidPackagePath)
            cmakeTemplate += 'set(HIFI_ANDROID_PRECOMPILED "{}")\n'.format(precompiled)
        else:
            cmakeTemplate += VcpkgRepo.CMAKE_TEMPLATE_NON_ANDROID
        cmakeConfig = cmakeTemplate.format(cmakeScript, cmakeScript, installPath, toolsPath, self.getTripletWithBuildType(self.hostTriplet)).replace('\\', '/')
        with open(self.configFilePath, 'w') as f:
            f.write(cmakeConfig)

